  "lasers-fibreoptics": [
    { label: "BJA Educ 2017", citation: "English J, Rana S. Management of the shared airway. BJA Education. 2017;17(8):265-270.", url: "https://doi.org/10.1093/bjaed/mkx009" },
    { label: "Cross & Plunkett Ch.18", citation: "Cross ME, Plunkett EVE. Physics, Pharmacology and Physiology for Anaesthetists. 2nd ed. Cambridge University Press; 2014. Chapter 18: Optics, Lasers, and Fibreoptics." },
    { label: "Middleton Ch.14", citation: "Middleton B, Phillips J, Thomas R. Physics in Anaesthesia. 2nd ed. Scion Publishing; 2019. Chapter 14: Lasers." },
    { label: "BJA Educ 2004", citation: "Dorsch JA. Lasers and fibreoptics in anaesthesia. BJA Education. 2004;4(4):128-131.", url: "https://doi.org/10.1093/bjaceaccp/mkh035" },
    { label: "Assoc Anaesth Airway Fire", citation: "Kane AD, Cook TM, Armstrong RA, et al. Management of complications of airway management: Guidelines from the Association of Anaesthetists. Anaesthesia. 2024;79(3):314-335.", url: "https://onlinelibrary.wiley.com/doi/10.1111/anae.15941", excerpt: "If an airway fire occurs, immediately and simultaneously: stop the flow of all airway gases and remove the tracheal tube. Extinguish any burning material with saline. Re-establish ventilation using air, avoiding nitrous oxide and supplemental oxygen until certain the fire is out. Inspect the airway by bronchoscopy and treat thermal/inhalational injury. Prevention includes a laser-resistant tube, lowest clinically acceptable FiO₂ (typically ≤0.30), avoidance of N₂O, and a saline-filled cuff (± methylene blue) protected by saline-soaked pledgets." },
  ],
