  "obstetric-anaesthesia": [
    { label: "BJA Educ 2019", citation: "Kinsella SM et al. Anaesthesia for caesarean section. BJA Education. 2019;19(9):299-305.", url: "https://doi.org/10.1016/j.bjae.2019.05.003" },
    { label: "OAA/DAS 2015", citation: "Mushambi MC, Kinsella SM, Popat M et al. OAA/DAS guidelines for the management of difficult and failed tracheal intubation in obstetrics. Anaesthesia. 2015;70:1286-1306.", url: "https://doi.org/10.1111/anae.13260", excerpt: "These guidelines, developed by the Obstetric Anaesthetists' Association and the Difficult Airway Society, describe a structured approach to airway management for general anaesthesia in obstetric patients, with Master, Obstetric and Rescue algorithms and emphasis on early decision-making about waking, surgery via supraglottic airway, or front-of-neck access. Reported failed-intubation rates in obstetrics are approximately 1 in 300 general anaesthetics." },
    { label: "MBRRACE-UK", citation: "Knight M et al. Saving Lives, Improving Mothers' Care (MBRRACE-UK). National Perinatal Epidemiology Unit, Oxford. 2022.", url: "https://www.npeu.ox.ac.uk/mbrrace-uk" },
    { label: "RCoA GPAS Ch 9 2024", citation: "Royal College of Anaesthetists. Guidelines for the Provision of Anaesthesia Services for an Obstetric Population (GPAS Chapter 9). RCoA; 2024.", url: "https://rcoa.ac.uk/gpas/chapter-9", excerpt: "Chapter 9 sets UK service standards for obstetric anaesthesia, including consultant-led 24/7 cover for high-risk delivery units, mandatory monitoring (AAGBI standards) for all neuraxial blocks and general anaesthetics, decision-to-delivery interval targets (<30 minutes for Category 1 caesarean section, <75 minutes for Category 2), availability of difficult-airway equipment and major-haemorrhage protocols, and team-based simulation training for failed intubation and maternal collapse." },
    { label: "OAA PDPH 2023", citation: "Russell R, Laxton C, Lucas DN, Niewiarowski J, Scrutton M, Stocks G. Treatment of obstetric post-dural puncture headache. Part 1: conservative and pharmacological management. Anaesthesia. 2019;74:61-77 (updated OAA guidance 2023).", url: "https://doi.org/10.1111/anae.14464", excerpt: "Accidental dural puncture during epidural insertion occurs in approximately 1% of obstetric epidurals, and 70–80% of affected women develop post-dural puncture headache. Epidural blood patch remains the most effective treatment, with around 70% achieving complete relief after a single patch." },
    { label: "OAA Nerve Injury 2023", citation: "Obstetric Anaesthetists' Association / RCoA. Management of postpartum nerve injuries following childbirth. OAA; 2023.", url: "https://www.oaa-anaes.ac.uk/postpartum-nerve-injuries", excerpt: "Postpartum neurological symptoms occur in approximately 1% of vaginal deliveries; the majority are intrinsic obstetric palsies (lateral femoral cutaneous, lumbosacral trunk, femoral, common fibular) rather than neuraxial complications. Red flags requiring urgent imaging include bilateral weakness, bladder/bowel dysfunction, saddle anaesthesia, and symptoms persisting beyond the expected dermatomal regression of the block." },
    { label: "NAP5", citation: "Pandit JJ, Andrade J, Bogod DG et al. 5th National Audit Project (NAP5) on accidental awareness during general anaesthesia: summary of main findings and risk factors. Br J Anaesth. 2014;113(4):549-559.", url: "https://doi.org/10.1093/bja/aeu313", excerpt: "Obstetric general anaesthesia carries the highest reported incidence of accidental awareness during general anaesthesia (~1:670). Contributory factors included thiopentone under-dosing, rapid sequence induction with delayed volatile, and use of neuromuscular blockade before adequate hypnotic effect." },
  ],
