  "ecmo": [
    { label: "ELSO Guidelines 2017", citation: "Extracorporeal Life Support Organization. ELSO Guidelines for Adult Respiratory Failure. Version 1.4. 2017.", url: "https://www.elso.org/ecmo-resources/elso-ecmo-guidelines.aspx", excerpt: "ECMO should be considered in acute severe respiratory failure when the risk of mortality is 50% or greater, and is indicated when the risk of mortality is 80% or greater. PaO2/FiO2 < 100 mmHg on FiO2 > 0.9 and/or Murray score 3–4 despite optimal care for 6 h or more identifies high-risk patients." },
    { label: "EOLIA 2018", citation: "Combes A, Hajage D, Capellier G, et al. Extracorporeal Membrane Oxygenation for Severe Acute Respiratory Distress Syndrome. N Engl J Med. 2018;378(21):1965-1975.", url: "https://doi.org/10.1056/NEJMoa1800385", excerpt: "Patients with very severe ARDS (PaO2:FIO2 < 50 mmHg for > 3 h; PaO2:FIO2 < 80 mmHg for > 6 h; or arterial pH < 7.25 with PaCO2 ≥ 60 mmHg for > 6 h) were randomly assigned to early VV-ECMO or continued conventional treatment with ECMO as rescue. 60-day mortality 35% vs 46% (relative risk 0.76; 95% CI 0.55–1.04; P = 0.09); trial stopped early for futility." },
    { label: "CESAR 2009", citation: "Peek GJ, Mugford M, Tiruvoipati R, et al. Efficacy and economic assessment of conventional ventilatory support versus extracorporeal membrane oxygenation for severe adult respiratory failure (CESAR): a multicentre randomised controlled trial. Lancet. 2009;374(9698):1351-1363.", url: "https://doi.org/10.1016/S0140-6736(09)61069-2", excerpt: "Referral to an ECMO-based management protocol increased survival without severe disability at 6 months from 47% to 63% (relative risk 0.69; 95% CI 0.05–0.97; P = 0.03) in adults with severe but potentially reversible respiratory failure." },
    { label: "ARREST 2020", citation: "Yannopoulos D, Bartos J, Raveendran G, et al. Advanced reperfusion strategies for patients with out-of-hospital cardiac arrest and refractory ventricular fibrillation (ARREST): a phase 2, single centre, open-label, adaptive, randomised clinical trial. Lancet. 2020;396(10265):1807-1816.", url: "https://doi.org/10.1016/S0140-6736(20)32338-2" },
    { label: "Prague OHCA 2022", citation: "Belohlavek J, Smalcova J, Rob D, et al. Effect of Intra-arrest Transport, Extracorporeal Cardiopulmonary Resuscitation, and Immediate Invasive Assessment and Treatment on Functional Neurologic Outcome in Refractory Out-of-Hospital Cardiac Arrest. JAMA. 2022;327(8):737-747.", url: "https://doi.org/10.1001/jama.2022.1025" },
    { label: "INCEPTION 2023", citation: "Suverein MM, Delnoij TSR, Lorusso R, et al. Early Extracorporeal CPR for Refractory Out-of-Hospital Cardiac Arrest. N Engl J Med. 2023;388(4):299-309.", url: "https://doi.org/10.1056/NEJMoa2204511" },
    { label: "ELSO Guidelines 2020", citation: "Richardson ASC, Tonna JE, Nanjayya V, et al. Extracorporeal Cardiopulmonary Resuscitation in Adults: Interim Guideline Consensus Statement From the Extracorporeal Life Support Organization. ASAIO J. 2021;67(3):221-228.", url: "https://doi.org/10.1097/MAT.0000000000001344" },
    { label: "BJA Educ ECMO 2018", citation: "Squiers JJ, et al. ECMO for adults with severe respiratory failure. Best Pract Res Clin Anaesthesiol. 2017;31(2):163-175.", url: "https://doi.org/10.1016/j.bpa.2017.07.002" },
    { label: "FICM ECMO 2021", citation: "Faculty of Intensive Care Medicine. ECMO for COVID-19 and Beyond: Standards and Guidelines. 2021.", url: "https://www.ficm.ac.uk" },
  ],
  "neurointensive-care": [
    { label: "BJA Educ 2018", citation: "Smith M. Monitoring intracranial pressure in traumatic brain injury. Anesth Analg. 2008;106(1):240-248.", url: "https://doi.org/10.1213/01.ane.0000297296.52006.8e" },
    { label: "BTF 2017", citation: "Carney N et al. Guidelines for the management of severe traumatic brain injury. 4th ed. Brain Trauma Foundation. Neurosurgery. 2017;80(1):6-15.", url: "https://doi.org/10.1227/NEU.0000000000001432" },
    { label: "BJA Educ 2014", citation: "Nathanson MH. Management of subarachnoid haemorrhage. BJA Education. 2014;14(2):68-73.", url: "https://doi.org/10.1093/bjaceaccp/mkt037" },
    { label: "AoMRC 2008", citation: "Academy of Medical Royal Colleges. A Code of Practice for the Diagnosis and Confirmation of Death. London: AoMRC; 2008.", url: "https://www.aomrc.org.uk/wp-content/uploads/2016/04/Code_Practice_Confirmation_Diagnosis_Death_1008-4.pdf", excerpt: "The arterial carbon dioxide tension (PaCO2) is greater than 6.65 kPa (50 mmHg) AND The arterial pH is less than 7.40." },
    { label: "ESICM Brain-Injury Ventilation 2020", citation: "Robba C et al. Mechanical ventilation in patients with acute brain injury: recommendations of the European Society of Intensive Care Medicine consensus. Intensive Care Med. 2020;46(12):2397-2410.", url: "https://doi.org/10.1007/s00134-020-06283-0", excerpt: "The consensus produced 36 statements (19 strong recommendations, 6 weak recommendations, 11 no recommendation) regarding airway management, non-invasive respiratory support, strategies for mechanical ventilation, rescue interventions for respiratory failure, ventilator liberation, and tracheostomy in brain-injured patients." },
    { label: "ESICM EEG 2013", citation: "Claassen J et al. Recommendations on the use of EEG monitoring in critically ill patients: consensus statement from the neurointensive care section of the ESICM. Intensive Care Med. 2013;39(8):1337-1351.", url: "https://doi.org/10.1007/s00134-013-2938-4", excerpt: "The panel recommends EEG in generalized convulsive status epilepticus and to rule out nonconvulsive seizures in brain-injured patients and in comatose ICU patients without primary brain injury who have unexplained and persistent altered consciousness. We recommend continuous over intermittent EEG for refractory status epilepticus." },
  ],
