  "icu-nutrition": [
    { label: "Curr Opin Anaesthesiol 2018 (ICU nutrition)", citation: "Berger MM, Pichard C. Nutrition in the ICU: new trends versus old-fashioned standard enteral feeding? Current Opinion in Anaesthesiology. 2018;31(2):190-195.", url: "https://doi.org/10.1097/aco.0000000000000571", excerpt: "Previously reported benefits of glutamine, selenium, and fish oil seem to have vanished in recent studies; however, studies on vitamin C, thiamine, and corticosteroid combinations show promising results." },
    { label: "ESPEN 2019", citation: "Singer P et al. ESPEN guideline on clinical nutrition in the intensive care unit. Clin Nutr. 2019;38(1):48-79.", url: "https://doi.org/10.1016/j.clnu.2018.08.037" },
    { label: "BJA Educ 2016", citation: "Preiser JC et al. ICU nutrition — progress and pitfalls. BJA Education. 2016;16(8):275-280.", url: "https://doi.org/10.1093/bjaed/mkv059" },
    { label: "NICE CG32", citation: "NICE. Nutrition support for adults: oral nutrition support, enteral tube feeding and parenteral nutrition (CG32). 2006 (updated 2017).", url: "https://www.nice.org.uk/guidance/cg32" },
    { label: "NICE-SUGAR 2009", citation: "NICE-SUGAR Investigators. Intensive versus conventional glucose control in critically ill patients. N Engl J Med. 2009;360:1283-1297.", url: "https://doi.org/10.1056/NEJMoa0810625" },
    { label: "EPaNIC 2011", citation: "Casaer MP et al. Early versus late parenteral nutrition in critically ill adults. N Engl J Med. 2011;365:506-517.", url: "https://doi.org/10.1056/NEJMoa1102662" },
    { label: "ESICM Early EN 2017", citation: "Reintam Blaser A et al. Early enteral nutrition in critically ill patients: ESICM clinical practice guidelines. Intensive Care Med. 2017;43(3):380-398.", url: "https://doi.org/10.1007/s00134-016-4665-0", excerpt: "We recommend early EN (within 48 h) in critically ill adult patients rather than delaying EN. We recommend early EN rather than early PN. In case of contraindications to oral intake and EN, parenteral nutrition should be implemented within three to seven days. Low-dose EN should be administered to patients receiving therapeutic hypothermia and increased after rewarming." },
  ],
